function fixture() {
  const root = mkdtempSync(join(tmpdir(), "union-dev-test-"));
  writeFileSync(join(root, "calc.mjs"), "export const add = (a, b) => a - b;\n");
  writeFileSync(join(root, "calc.test.mjs"), [
    'import test from "node:test";',
    'import assert from "node:assert/strict";',
    'import { add } from "./calc.mjs";',
    'test("adds", () => assert.equal(add(2, 3), 5));',
    "",
  ].join("\n"));
  return root;
}

function response(job, action) {
  return { id: job.id, text: JSON.stringify(action), attempts: [{ endpoint: "mock-free-cloud", outcome: "completion" }] };
}

test("cloud actor reads, edits, verifies, integrates, and leaves reusable trajectory memory", async () => {
  const territory = fixture(), ledgerRoot = join(territory, "trajectory-ledger");
  let wave = 0;
  const dispatch = async (jobs) => {
    wave += 1;
    if (wave === 1) return jobs.map((job) => response(job, { action: "read", args: { path: "calc.mjs" }, reason: "inspect the implementation before changing it" }));
    return jobs.map((job) => response(job, {
      action: "edit",
      args: { path: "calc.mjs", blocks: "<<<<<<< SEARCH\nexport const add = (a, b) => a - b;\n=======\nexport const add = (a, b) => a + b;\n>>>>>>> REPLACE" },
      reason: "replace subtraction with the required addition",
    }));
  };
  const result = await runMission({
    id: "urn:test:mission:addition",
    objective: "Repair the add function so the declared test passes.",
    territory,
    verifyCommand: "node --test calc.test.mjs",
    actors: 2,
    maxRounds: 3,
    apply: true,
  }, { dispatch, ledgerRoot });

  assert.equal(result.outcome.verified, true);
  assert.equal(result.outcome.integrated, true);
  assert.equal(result.metrics.directInteractiveModelCalls, 0);
  assert.equal(result.metrics.usefulCompletions, 4);
  assert.match(readFileSync(join(territory, "calc.mjs"), "utf8"), /a \+ b/);
  assert.equal(existsSync(result.ledgerPath), true);
  assert.equal(recallTrajectories("repair addition function", { ledgerRoot })[0].changedPaths[0], "calc.mjs");
});

test("a concurrently changed source is certified as a protected border and not overwritten", async () => {
  const territory = fixture(), ledgerRoot = join(territory, "trajectory-ledger");
  let wave = 0;
  const dispatch = async (jobs) => {
    wave += 1;
    if (wave === 1) return jobs.map((job) => response(job, { action: "read", args: { path: "calc.mjs" }, reason: "inspect current source before editing" }));
    writeFileSync(join(territory, "calc.mjs"), "export const add = (a, b) => Number(a) + Number(b);\n");
    return jobs.map((job) => response(job, {
      action: "edit",
      args: { path: "calc.mjs", blocks: "<<<<<<< SEARCH\nexport const add = (a, b) => a - b;\n=======\nexport const add = (a, b) => a + b;\n>>>>>>> REPLACE" },
      reason: "repair the isolated candidate",
    }));
  };
  const result = await runMission({
    objective: "Repair addition without overwriting concurrent source work.",
    territory,
    verifyCommand: "node --test calc.test.mjs",
    actors: 1,
    maxRounds: 2,
    apply: true,
  }, { dispatch, ledgerRoot });

  assert.equal(result.outcome.verified, true);
  assert.equal(result.outcome.integrated, false);
  assert.equal(result.outcome.classification, "protected-border");
  assert.match(readFileSync(join(territory, "calc.mjs"), "utf8"), /Number\(a\)/);
});

test("runMission stops dispatching after minVerifiedCandidates is satisfied in the first wave", async () => {
  const territory = fixture(), ledgerRoot = join(territory, "trajectory-ledger");
  let dispatchCalls = 0;
  const dispatch = async (jobs) => {
    dispatchCalls += 1;
    return jobs.map((job) => response(job, {
      action: "edit",
      args: {
        path: "calc.mjs",
        blocks: "<<<<<<< SEARCH\nexport const add = (a, b) => a - b;\n=======\nexport const add = (a, b) => a + b;\n>>>>>>> REPLACE",
      },
      reason: "replace subtraction with addition",
    }));
  };
  const result = await runMission({
    id: "urn:test:mission:early-quorum",
    objective: "Repair the add function so the declared test passes.",
    territory,
    verifyCommand: "node --test calc.test.mjs",
    actors: 3,
    maxRounds: 10,
    minVerifiedCandidates: 1,
    apply: false,
  }, { dispatch, ledgerRoot });

  assert.equal(result.outcome.verified, true);
  assert.equal(result.metrics.rounds, 1);
  assert.equal(dispatchCalls, 1);
});

test("a verification-passing but semantically rejected candidate is not integrated", async () => {
  const territory = fixture(), ledgerRoot = join(territory, "trajectory-ledger");
  const dispatch = async (jobs) => jobs.map((job) => response(job, {
    action: "edit",
    args: { path: "calc.mjs", blocks: "<<<<<<< SEARCH\nexport const add = (a, b) => a - b;\n=======\nexport const add = (a, b) => a + b;\n>>>>>>> REPLACE" },
    reason: "make the execution gate pass",
  }));
  const result = await runMission({
    id: "urn:test:mission:semantic-rejection",
    objective: "Require a different semantic change than addition.",
    territory,
    verifyCommand: "node --test calc.test.mjs",
    actors: 1,
    maxRounds: 2,
    apply: true,
  }, {
    dispatch,
    ledgerRoot,
    reviewCandidate: async () => ({ type: "IndependentSemanticAcceptance", accepted: false, reviews: [{ accepted: false, reason: "the patch only repairs addition and does not satisfy the stated objective" }] }),
  });
  assert.equal(result.outcome.candidateVerified, true);
  assert.equal(result.outcome.verified, false);
  assert.equal(result.outcome.classification, "semantic-review-rejected");
  assert.match(readFileSync(join(territory, "calc.mjs"), "utf8"), /a - b/);
});

test("actor circuit opens after maxConsecutiveRefusals and stops before maxRounds with no verified candidate", async () => {
  const territory = fixture(), ledgerRoot = join(territory, "trajectory-ledger");
  let dispatchCalls = 0;
  const dispatch = async (jobs) => {
    dispatchCalls += 1;
    return jobs.map((job) => ({ id: job.id, refusal: { type: "no-feasible-endpoint" }, attempts: [] }));
  };
  const result = await runMission({
    id: "urn:test:mission:circuit-breaker",
    objective: "Repair the add function so the declared test passes.",
    territory,
    verifyCommand: "node --test calc.test.mjs",
    actors: 1,
    maxRounds: 5,
    maxConsecutiveRefusals: 2,
    apply: false,
  }, { dispatch, ledgerRoot });

  assert.equal(result.outcome.verified, false);
  assert.equal(result.outcome.classification, "unresolved");
  assert.equal(result.metrics.verifiedCandidates, 0);
  assert.equal(dispatchCalls, 2);
  assert.equal(result.metrics.rounds, 2);
  assert.equal(result.actors[0].status, "refused");
});

